import {dir,root,sha,load,inputs,verifyPackage} from './package-lib.mjs';
const arg=process.argv[2];assert.ok(arg&&isAbsolute(arg),'new external absolute output required');
const target=join(await realpath(dirname(resolve(arg))),basename(resolve(arg))),rel=relative(await realpath(root),target);assert.ok(rel&&!(rel!== '..'&&!rel.startsWith('..'+sep)&&!isAbsolute(rel)),'output inside source');
const policy=await load(join(dir,'source-inputs.json'));await inputs(policy);await mkdir(target);const staging=join(target,'build'),out=join(target,'package');await mkdir(staging);await mkdir(out);await mkdir(join(staging,'tmp'));
const env={...process.env,WRANGLER_SEND_METRICS:'false',WRANGLER_LOG_PATH:join(staging,'wrangler.log'),TMPDIR:join(staging,'tmp')};
const built=spawnSync(process.execPath,[join(root,'node_modules/wrangler/bin/wrangler.js'),'deploy','--dry-run','--config',join(dir,'wrangler.jsonc'),'--outdir',staging,'--metafile',join(staging,'metafile.json')],{cwd:root,env,encoding:'utf8'});await writeFile(join(staging,'build.log'),built.stdout+built.stderr);assert.equal(built.status,0,'actual Wrangler dry-run');
const raw=await load(join(staging,'metafile.json')),output=Object.entries(raw.outputs).find(([p])=>p.endsWith('/index.js'))?.[1];assert.ok(output);assert.deepEqual(output.exports,['createReceivingService','default']);assert.deepEqual(output.imports.map(x=>x.path).sort(),['buffer','stream']);assert.ok(output.imports.every(x=>x.external&&x.kind==='import-statement'));
const normalize=name=>name.startsWith('node-built-in-modules:')?name:relative(root,resolve(dir,name)).split(sep).join('/');
const graph=Object.fromEntries(await Promise.all(Object.entries(raw.inputs).map(async([name,v])=>{const n=normalize(name);assert.ok(policy.graph_inputs.includes(n),'unexpected compiled input '+n);return[n,{bytes:v.bytes,sha256:n.startsWith('node-built-in-modules:')?null:sha(await readFile(join(root,n))),imports:v.imports.map(i=>({kind:i.kind,path:i.path==='<runtime>'?'<esbuild-runtime>':i.external?i.path:normalize(i.path),external:!!i.external}))}];})));
assert.deepEqual(Object.keys(graph).sort(),policy.graph_inputs);for(const [name,v]of Object.entries(graph))if(v.sha256)assert.equal(v.sha256,policy.inputs_sha256[name],'compiled input drift '+name);
const meta={classification:'EXACT_SELECTED_PRODUCTION_IMPORT_GRAPH',inputs:graph,exports:output.exports,runtime_imports:output.imports.map(x=>x.path).sort(),virtual_inputs:Object.keys(graph).filter(x=>x.startsWith('node-built-in-modules:')).sort(),compatibility:policy.compatibility,selected_production_functions:policy.selected_production_functions};
let bundle=await readFile(join(staging,'index.js'),'utf8');bundle=bundle.replace(/^\/\/# sourceMappingURL=.*\n?/gm,'');assert.ok(!bundle.includes('/Volumes/')&&!bundle.includes('/Users/'));
// These are supplemental controls; the complete pinned graph and exact entry
