for(const value of ['qualifySyntheticStatus','vi.mock(','createSoftwareStub','ZEML4LPXH4.dev.djconnect.ios'])assert.ok(!bundle.includes(value),value);
await writeFile(join(out,'receiving.mjs'),bundle);await writeFile(join(out,'metafile.json'),JSON.stringify(meta,null,2)+'\n');await copyFile(join(dir,'source-inputs.json'),join(out,'SOURCE_MANIFEST.json'));
for(const [dest,source]of Object.entries(policy.copies)){await mkdir(dirname(join(out,dest)),{recursive:true});await copyFile(join(root,source),join(out,dest));}
const nativeName='@esbuild/'+process.platform+'-'+process.arch,nativeDir=join(root,'node_modules',nativeName);assert.ok(['darwin','linux'].includes(process.platform));const nativeMeta=await load(join(nativeDir,'package.json')),lock=await load(join(root,'package-lock.json'));assert.equal(nativeMeta.version,(await load(join(root,'node_modules/esbuild/package.json'))).version);assert.equal(lock.packages['node_modules/'+nativeName].version,nativeMeta.version);const nativeTool={package:nativeName,version:nativeMeta.version,lock_integrity:lock.packages['node_modules/'+nativeName].integrity,binary_sha256:sha(await readFile(join(nativeDir,'bin/esbuild')))};
const hashes={};for(const name of policy.deliverables)hashes[name]=sha(await readFile(join(out,name)));
const proof={classification:'PRIVATE_RECEIVING_SOURCE_DISTRIBUTION_NOT_RUNTIME_ADMISSION',source_manifest_sha256:sha(await readFile(join(dir,'source-inputs.json'))),files_sha256:hashes,public_activation:false,genuine_native_qualification:false,production_schema_installed:false,source_maps_delivered:false,toolchain:{node:process.version,wrangler:(await load(join(root,'node_modules/wrangler/package.json'))).version,esbuild:(await load(join(root,'node_modules/esbuild/package.json'))).version,platform:process.platform,arch:process.arch,native_esbuild:nativeTool},compatibility:policy.compatibility};
await writeFile(join(out,'package-proof.json'),JSON.stringify(proof,null,2)+'\n');const digest=sha(await readFile(join(out,'package-proof.json')));await verifyPackage(out,digest);console.log(JSON.stringify({package:out,proof_sha256:digest,module_sha256:hashes['receiving.mjs'],files:policy.deliverables.length+1,production_admission:false}));
